// Per-column sum: walk row-major instead of column-major. The outer loop
// goes over rows and the inner loop walks a contiguous row, so every
// inner-loop access is to consecutive memory. We accumulate directly into
// the per-column output buffer.
std::vector<double> Matrix::SumPerColumn() const {
    std::vector<double> result(cols_, 0.0);
    for (std::size_t r = 0; r < rows_; ++r) {
        for (std::size_t c = 0; c < cols_; ++c) {
            result[c] += data_[r * cols_ + c];
        }
    }
    return result;
}

// Per-column sum: walk row-major instead of column-major. The outer loop
// goes over rows and the inner loop walks a contiguous row, so every
// inner-loop access is to consecutive memory. We accumulate directly into
// the per-column output buffer.
std::vector<double> Matrix::SumPerColumn() const {
    std::vector<double> result(cols_, 0.0);
    for (std::size_t r = 0; r < rows_; ++r) {
        for (std::size_t c = 0; c < cols_; ++c) {
            result[c] += data_[r * cols_ + c];
        }
    }
    return result;
}

